const upsertLeaderboard = `-- name: UpsertLeaderboard :one
INSERT INTO leaderboards (period, scope, kind, computed_for)
VALUES ($1, $2, $3, CURRENT_DATE)
ON CONFLICT (period, scope, kind, computed_for) DO UPDATE SET created_at = NOW()
RETURNING id
`

type UpsertLeaderboardParams struct {
	Period string `json:"period"`
	Scope  string `json:"scope"`
	Kind   string `json:"kind"`
}

func (q *Queries) UpsertLeaderboard(ctx context.Context, arg UpsertLeaderboardParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, upsertLeaderboard, arg.Period, arg.Scope, arg.Kind)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertPortfolioStats = `-- name: UpsertPortfolioStats :exec
INSERT INTO portfolio_stats (portfolio_id, likes, views_7d, views_30d, comments, assessment_avg, quality, engagement, trending)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (portfolio_id) DO UPDATE SET
  likes = EXCLUDED.likes, views_7d = EXCLUDED.views_7d, views_30d = EXCLUDED.views_30d,
  comments = EXCLUDED.comments, assessment_avg = EXCLUDED.assessment_avg,
  quality = EXCLUDED.quality, engagement = EXCLUDED.engagement, trending = EXCLUDED.trending,
  computed_at = NOW()
`

type UpsertPortfolioStatsParams struct {
	PortfolioID   pgtype.UUID    `json:"portfolio_id"`
	Likes         int32          `json:"likes"`
	Views7d       int32          `json:"views_7d"`
	Views30d      int32          `json:"views_30d"`
	Comments      int32          `json:"comments"`
	AssessmentAvg pgtype.Numeric `json:"assessment_avg"`
	Quality       pgtype.Numeric `json:"quality"`
	Engagement    pgtype.Numeric `json:"engagement"`
	Trending      pgtype.Numeric `json:"trending"`
}

func (q *Queries) UpsertPortfolioStats(ctx context.Context, arg UpsertPortfolioStatsParams) error {
	_, err := q.db.Exec(ctx, upsertPortfolioStats,
		arg.PortfolioID,
		arg.Likes,
		arg.Views7d,
		arg.Views30d,
		arg.Comments,
		arg.AssessmentAvg,
		arg.Quality,
		arg.Engagement,
		arg.Trending,
	)
	return err
}
